    "effect": "[起動メイン]\n[レストにする]\n[このカードを退場させる]\n自分の山札の上から5枚見る。その中から必要エナジーが2以下で消費APが1の特徴に「万事屋」を持つキャラカードを1枚まで自分の場にレストで登場させるか〈万事屋銀ちゃん〉を1枚まで自分のエナジーLにレストで登場させる。残りを望む順で自分の山札の下に置く。この効果で登場させなかった場合、このカードを手札に加える。",
