    "generatedEnergy": "蓝色×1",
    "effect": "[レイド]\nカード名に「オーズ」を含むキャラ アクティブにし、フロントLに移動できる\n自分の手札が7枚以上の場合、このキャラは\n[ダメージ（2）]\nを得る。\n[登場時]\n自分の場か自分の手札の〈アンク〉を1枚リムーブエリアに置いてもよい。そうした場合、カードを1枚まで引き、このキャラはこのターン中、BP+1000と\n[インパクト（1）]\nを得る。\n[起動メイン]\n[フロントLにある場合]\n[ターン1]\n自分の手札の必要エナジーが同じカードを3枚場外に置く。そうした場合、カードを1枚引き、このメインフェイズ終了時、カードを3枚引く。",
    "effectZh": "[雷击]\n卡片名称包含「OOO」的角色激活，并移动至前线L。\n若己方手札7张以上，此角色获得\n[伤害（2）]。\n[登场时]\n可将己方场上或己方手札的1枚〈未解〉放置于场外。如此操作后，抽卡最多1张，且本回合中该角色BP+1000并获得\n[冲击（1）]。\n[启动主阶段]\n[若位于前线L时]\n[第1次]\n将己方手札中的必要能量相同的3张卡片放置于场外。如此操作后，抽卡最多1张，且本主阶段结束时再抽卡最多3张。",
    "trigger": "[レイド]\nこのカードを手札に加えるか、必要エナジーを満たしている場合、レイドさせる。",
    "triggerZh": "[雷击]\n将此牌加入手札或满足必要能量的情况下，发动雷击。",
    "officialUrl": "https://www.unionarena-tcg.com/jp/cardlist/detail.php?card_no=UAPR%2FKMR-1-039",
    "variant": "普通版",
    "image": "/cards/series-570901/UAPR_KMR-1-039.png"
