    "effect": "[レイド]\nカード名に「ガヴ」を含むキャラ アクティブにし、フロントLに移動できる\nこのターン中にこのキャラが自分の効果で登場している場合、このキャラはBP+1000と\n[インパクト（1）]\nを得る。\nこのキャラのアタック終了時、自分がこのアタックフェイズでレイドしていない場合、「自分の手札の〈仮面ライダーガヴ オーバーモード〉を1枚公開し、自分の場の〈ゴチゾウ〉を1枚退場させる。」をしてもよい。そうした場合、レイド状態のこのキャラの一番上のカードを手札に戻し、公開したカードをこのキャラのレイド元のカードにレイドさせる。\n[登場時]\n[アタック時]\n自分の手札から〈ゴチゾウ〉を1枚まで自分のエナジーLにレストで登場させる。",
    "effectZh": "[雷击]\n名字包含「Gav」的角色激活，并可以移动到前线 L。\n如果本回合该角色通过自己的效果登场过，则该角色获得 BP+1000\n和 [冲击（1）]。\n在该角色的攻击结束时，如果自己在本攻击阶段未进行雷击，则可以选择公开自己手牌中的「假面骑士 Gav Over Mode」一张，并让场上的「Gochizou」退场。如此操作后，将处于雷击状态的该角色最上方的卡片放回手牌，并将公开的卡片对该角色的原雷击位置执行雷击。\n[登场时]\n[攻击时]\n从自己手牌中最多选择 1 张「Gochizou」以横置状态进入自己的能量 L。",
    "trigger": "[レイド]\nこのカードを手札に加えるか、必要エナジーを満たしている場合、レイドさせる。",
    "triggerZh": "[雷击]\n将该卡加入手牌，或满足所需能量的情况下，对该卡执行雷击。",
